'use strict';
const KEY='ott-project-demo-v1';
const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>[...p.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={play:'▶',pause:'Ⅱ',save:'+',saved:'✓'};
function seed(){
 const names=['별의 항로','푸른 오후','달빛 도서관','도시의 온도','깊은 바다','오래된 정원','낯선 새벽','작은 우주'];
 const genres=['SF','드라마','판타지','드라마','다큐멘터리','드라마','스릴러','애니메이션'];
 const descriptions=['잊힌 신호를 따라 떠나는 두 탐험가의 여정. 우주 끝에서 새로운 이야기가 시작됩니다.','낯선 도시에서 만난 이들의 하루. 작은 선택이 서로의 계절을 바꿉니다.','밤이 깊어지면 문을 여는 도서관. 책 속의 기억을 지키는 사람들의 이야기.','스쳐 가는 일상 속에 남겨진 따뜻한 순간들을 따라갑니다.','아직 발견하지 못한 바다의 풍경과 생명을 만나는 시간.','오래된 정원에서 다시 만난 두 사람이 잃어버린 계절을 되찾습니다.','불이 꺼진 도시에서 하나의 단서를 따라가는 미스터리.','작은 별에 사는 친구들의 크고 새로운 모험이 시작됩니다.'];
 const contents=names.map((title,i)=>({id:'c'+(i+1),title,genre:genres[i],type:[1,3].includes(i)?'series':'movie',year:'2026',rating:'12+',actors:i%2?'김하늘, 이도윤':'정서윤, 강우진',tags:i%2?'청춘, 일상':'모험, 발견',description:descriptions[i],art:i%6,published:i<6,ready:i!==6,video:i===6?'':'sample.mp4',image:'cover.svg',subtitles:['한국어','영어'],episodes:[1,3].includes(i)?[1,2,3].map(n=>({id:'e'+n,season:1,no:n,title:['새로운 시작','서로의 계절','낯선 오후'][n-1],ready:true,published:true,video:'episode'+n+'.mp4'})):[],deleted:false,created:100-i}));
 return {version:1,contents,users:{a:{id:'a',nickname:'별보는사람',role:'member',watchlist:['c1','c2','c5'],history:{c2:1104,c1:420}},b:{id:'b',nickname:'도시산책자',role:'member',watchlist:['c4','c6'],history:{c4:620,c6:200}},admin:{id:'admin',nickname:'관리자 A',role:'admin',watchlist:[],history:{}}},current:null,popularitySamples:popularitySeed(),channels:[{id:'ch1',name:'문화',description:'일상 속 문화 이야기를 전합니다.',url:'https://stream.example/live/channel01.m3u8',published:true},{id:'ch2',name:'여행',description:'도시와 자연을 함께 걷는 시간',url:'https://stream.example/live/channel02.m3u8',published:true}],programs:[{id:'p1',channel:'ch1',title:'오늘의 문화',start:'14:00',end:'15:00'},{id:'p2',channel:'ch1',title:'도시 산책',start:'15:00',end:'16:00'},{id:'p3',channel:'ch1',title:'새로운 시선',start:'16:00',end:'17:00'}],jobs:[{id:'job1',content:'c7',episode:null,status:'실패',resolution:'1080p',error:'원본 파일을 읽을 수 없습니다.'}],logs:[{actor:'관리자 A',time:'2026.11.07 14:32',type:'공개 전환',target:'c1',before:{published:false},after:{published:true},result:'성공'}],events:[],model:'MODEL-007',dataVersion:10,training:[],recommendationFailure:false};
}
// Demo-only aggregate input; the production service will aggregate server-side watch logs.
function popularitySeed(){
 const stamp=Date.now()-3600000;
 return [['c2',12],['c1',9],['c4',7],['c5',5],['c3',4],['c6',3]].flatMap(([content,count])=>Array.from({length:count},(_,i)=>({member:'sample-viewer-'+i,content,seconds:300+i*30,time:stamp})));
}
let db;try{db=JSON.parse(localStorage.getItem(KEY));if(!db||db.version!==1)db=seed();}catch{db=seed();}
if(!Array.isArray(db.popularitySamples)){db.popularitySamples=popularitySeed();delete db.manual;}
let memoryOnly=false;function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch{memoryOnly=true;}}
const user=()=>db.users[db.current]||null, isAdmin=()=>user()?.role==='admin';
const all=()=>db.contents.filter(c=>!c.deleted),get=id=>db.contents.find(c=>c.id===id&&!c.deleted);
// [CMS 연결] ------------------------------------------------------------------------------------
// cms-config.js가 CMS 주소(window.CMS_API_BASE)를 정해 주면 시청자 화면(홈·검색·상세·재생)은 CMS API의
// 데이터를 쓴다. 주소가 없으면(null) 예전처럼 내장 샘플 데이터로 동작한다. 관리자 화면은 아직 샘플 데이터다.
const CMS_API=typeof window!=='undefined'&&window.CMS_API_BASE!=null&&typeof fetch==='function'?String(window.CMS_API_BASE).replace(/\/$/,''):null;
let cms={contents:CMS_API===null?null:[],loading:CMS_API!==null},media=null;
const publics=()=>cms.contents||all().filter(c=>c.published);              // 시청자에게 보이는 목록
const pick=id=>cms.contents?cms.contents.find(c=>c.id===id):get(id);         // 시청자 화면에서 콘텐츠 하나 찾기
const art=c=>c.poster||`assets/art-${c.art}.svg`;                            // 포스터: CMS(버킷) 또는 샘플 아트워크
const resLabel=c=>c.height?(c.height>=2160?'4K':c.height+'p'):'';
// CMS 응답 한 건을 목업이 쓰던 콘텐츠 모양으로 바꾼다
const fromCms=i=>({id:i.id,cms:true,title:i.title,genre:i.genre||'',type:'movie',year:String(i.releaseYear??''),rating:i.ageRating==='ALL'?'전체':i.ageRating+'+',actors:i.actors||'',tags:i.tags||'',description:i.description||'',art:0,poster:i.posterUrl?CMS_API+i.posterUrl:null,published:true,ready:true,episodes:[],subtitles:[],deleted:false,created:Date.parse(i.publishedAt)||0,duration:i.runtimeSec||0,height:i.videoHeight||0});
// 공개된 영화 목록을 CMS에서 페이지 단위로 모두 받아 온다 (검색·홈 구성은 지금처럼 브라우저에서 한다)
async function loadCms(){
 if(CMS_API===null)return;
 try{
  const items=[];let page=0,data;
  do{const res=await fetch(`${CMS_API}/api/contents?page=${page++}&size=500`);if(!res.ok)throw new Error('HTTP '+res.status);data=await res.json();items.push(...data.items);}while(data.hasNext);
  cms.contents=items.map(fromCms);
 }catch(e){cms.contents=null;console.warn('CMS 연결 실패',e);toast('CMS에 연결하지 못해 내장 샘플 데이터로 표시합니다.');}
 cms.loading=false;render();
}
// ----------------------------------------------------------------------------------------------
let demoActor='new',editTab='basic',myTab='watchlist',catalogLimit=10,searchState={q:'',type:'all',genre:'all'},liveChannel='ch1',selectedEpisode=null,player={content:null,position:0,playing:false,speed:1,quality:'자동',subtitle:'한국어',volume:.7},playTimer=null,returnFocus=null;
const now=()=>new Date().toLocaleString('ko-KR',{hour12:false}),uid=prefix=>prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
function audit(type,target,before,after){db.logs.unshift({actor:user()?.nickname||'시연 관리자',time:now(),type,target,before,after,result:'성공'});persist();}
function event(kind){if(!user()||!player.content)return;const e={id:uid('evt'),member:user().id,content:player.content,type:kind,time:Date.now(),position:Math.floor(player.position)};db.events.push(e);if(db.events.length>300)db.events.shift();persist();}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3000);}
function go(path){if(location.hash.slice(1)===path)render();else location.hash=path;}
function closeModal(){$('#modal-root').innerHTML='';returnFocus?.focus();}
function modal(title,body,wide=false){returnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="close" data-act="close" aria-label="닫기">×</button></div>${body}</section></div>`;setTimeout(()=>$('#modal-root input, #modal-root button')?.focus(),0);}
const btn=(label,act,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-act="${act}" ${extra}>${label}</button>`;
const badge=s=>`<span class="badge ${['완료','공개','사용 중','성공'].some(x=>s.includes(x))?'ok':s.includes('실패')?'fail':s.includes('처리')||s.includes('대기')?'wait':''}">${esc(s)}</span>`;
const empty=(title,body,action='')=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(body)}</p>${action}</div>`;
function nav(active='home'){return `<header class="nav"><a href="#home" class="brand">OTT <span>PROJECT</span></a><nav class="navlinks" aria-label="주 메뉴">${[['home','홈'],['search','탐색·검색'],['my','내 콘텐츠'],['live','라이브']].map(([p,n])=>`<a class="navlink ${active===p?'active':''}" href="#${p}">${n}</a>`).join('')}</nav><div class="navuser">${user()?`<span class="avatar">${esc(user().nickname[0])}</span><a class="user-name" href="#my">${esc(user().nickname)}</a>${isAdmin()?'<a class="btn small" href="#admin/contents">관리</a>':''}`:`<a href="#login" class="btn small">로그인</a>`}</div></header>`;}
function footer(){return `<footer class="footer"><span>OTT PROJECT · 학교·전시 프로젝트 UI 검토본</span><span>자체 샘플 작품 · 실제 소셜 인증·스트리밍 서비스 아님${memoryOnly?' · 저장 제한: 현재 창에서만 유지':''}</span></footer>`;}
function demoBar(){return `<aside class="demo-bar" aria-label="목업 시연 도구"><span class="demo-dot"></span><span>클릭형 목업</span><button data-act="demo">시연 도구</button><button data-act="help" class="optional">안내</button></aside>`;}
function card(c,progress=false){const saved=user()?.watchlist.includes(c.id),pos=user()?.history[c.id]||0;return `<article class="card"><button class="card-open" data-act="detail" data-id="${c.id}"><div class="artwrap"><img src="${art(c)}" alt="${esc(c.title)} 샘플 아트워크" loading="lazy"><span class="art-title">${esc(c.title)}</span>${progress?`<div class="progress"><span style="width:${Math.min(100,pos/(c.duration||2520)*100)}%"></span></div>`:''}</div><div class="card-title">${esc(c.title)}</div><div class="meta">${progress?time(pos)+'부터 이어보기':`${esc(c.year)} · ${c.type==='series'?'시리즈':'영화'} · ${esc(c.genre)}${resLabel(c)?' · '+resLabel(c):''}`}</div></button><button class="card-save ${saved?'saved':''}" data-act="watchlist" data-id="${c.id}" aria-label="${esc(c.title)} ${saved?'찜 해제':'찜 추가'}" aria-pressed="${!!saved}">${saved?'✓':'+'}</button></article>`;}
function rail(title,items,progress=false){return `<section class="rail"><div class="rail-head"><h2>${title}</h2><a href="#${progress?'my':'search'}">더 보기 →</a></div>${items.length?`<div class="cards">${items.slice(0,5).map(c=>card(c,progress)).join('')}</div>`:empty('아직 콘텐츠가 없습니다','이야기를 둘러보고 나만의 목록을 채워 보세요.','<a class="btn small" href="#search">콘텐츠 둘러보기</a>')}</section>`;}
function popularity(at=Date.now()){
 const cutoff=at-7*86400000, totals=new Map();
 for(const row of db.popularitySamples){
  if(row.time<cutoff||row.time>at||!Number.isFinite(row.seconds)||row.seconds<=0||!row.member)continue;
  const c=pick(row.content);if(!c?.published||db.users[row.member]?.role==='admin')continue;
  const key=JSON.stringify([row.member,row.content]), old=totals.get(key);
  if(old)old.seconds+=row.seconds;else totals.set(key,{member:row.member,content:row.content,seconds:row.seconds});
 }
 const grouped=new Map();
 for(const row of totals.values()){
  if(row.seconds<30)continue;
  const total=grouped.get(row.content)||{content:pick(row.content),viewers:0,seconds:0};
  total.viewers++;total.seconds+=row.seconds;grouped.set(row.content,total);
 }
 return [...grouped.values()].sort((a,b)=>b.viewers-a.viewers||b.seconds-a.seconds||a.content.id.localeCompare(b.content.id));
}
function popularContents(){return popularity().map(row=>row.content);}
function fallbackContents(){const popular=popularContents();return popular.length?popular:[...publics()].sort((a,b)=>b.created-a.created);}
function recordWatch(seconds){
 if(!player.playing||!user()||isAdmin()||!pick(player.content)?.published||!Number.isFinite(seconds)||seconds<=0||seconds>2)return;
 const stamp=Date.now(), day=Math.floor(stamp/86400000);
 db.popularitySamples=db.popularitySamples.filter(row=>row.time>=stamp-7*86400000);
 const row=db.popularitySamples.find(row=>row.member===user().id&&row.content===player.content&&Math.floor(row.time/86400000)===day);
 if(row)row.seconds+=seconds;else db.popularitySamples.push({member:user().id,content:player.content,seconds,time:stamp});
}
function recommended(){if(!user()||!Object.keys(user().history).length||db.recommendationFailure)return fallbackContents();const order=user().id==='b'?['c4','c6','c3','c2','c5']:['c1','c2','c5','c3','c4'];const list=order.map(pick).filter(c=>c?.published);return list.length?list:fallbackContents();}
function hero(c,detail=false){return `<section class="hero"><img class="hero-art" src="${art(c)}" alt=""><div class="hero-copy"><div class="eyebrow">${detail?'ORIGINAL STORY':'THIS WEEK / FEATURED STORY'}</div><h1>${esc(c.title)}</h1><div class="meta">${esc(c.year)} · ${esc(c.rating)} · ${esc(c.genre)}${c.type==='series'?' · 시즌 '+new Set(c.episodes.map(e=>e.season)).size+'개':''}${resLabel(c)?' · '+resLabel(c)+' · '+time(c.duration):''}</div><p>${esc(c.description)}</p><div class="actions">${detail?btn((user()?.history[c.id]?'이어서 감상':'재생하기')+' ▶','play','primary',`data-id="${c.id}"`)+btn((user()?.watchlist.includes(c.id)?'✓ 찜한 콘텐츠':'+ 찜하기'),'watchlist','',`data-id="${c.id}"`):btn('상세 보기','detail','primary',`data-id="${c.id}"`)}</div></div></section>`;}
function home(){const list=publics(),featured=list.find(c=>c.id==='c1')||list[0];return nav('home')+`<main class="container">${featured?hero(featured):empty('새로운 이야기를 준비 중입니다','공개된 콘텐츠가 곧 표시됩니다.')}${user()&&Object.keys(user().history).length&&!db.recommendationFailure?rail(`${esc(user().nickname)}님을 위한 추천`,recommended()):''}${user()?rail('이어서 감상하기',Object.keys(user().history).sort((a,b)=>(user().recent?.indexOf(a)??99)-(user().recent?.indexOf(b)??99)).map(pick).filter(c=>c?.published),true):''}${rail('새로 공개된 이야기',[...list].sort((a,b)=>b.created-a.created))}${rail(popularContents().length?'지금 인기 있는 콘텐츠':'인기 데이터 준비 중 · 새로 공개된 이야기',fallbackContents())}${user()?rail('내가 찜한 콘텐츠',user().watchlist.map(pick).filter(c=>c?.published)):''}</main>`+footer();}
function login(){return nav()+`<main class="auth"><section class="auth-panel"><div class="eyebrow">YOUR NEXT STORY</div><h1>다음 이야기를<br>만나보세요</h1><p>소셜 계정으로 간편하게 시작하고<br>좋아하는 콘텐츠를 이어서 감상하세요.</p>${btn('소셜로 시작하기','social','primary full')}<p style="font-size:13px;margin:8px 0 28px">처음 이용하는 경우 인증 후 닉네임을 설정하면 가입이 완료됩니다.</p><a href="#home" class="muted">← 공개 콘텐츠 둘러보기</a></section></main>`;}
function signup(){return nav()+`<main class="auth"><section class="auth-panel"><div class="eyebrow">소셜 인증 완료 · 시연</div><h1>어떻게 불러드릴까요?</h1><p>콘텐츠를 감상하기 전에 닉네임을 설정해 주세요.</p><form id="signup-form" novalidate><div class="field"><label for="nickname">닉네임 *</label><input id="nickname" name="nickname" autocomplete="nickname" placeholder="사용할 닉네임"><div class="error" id="signup-error" aria-live="polite"></div></div><button class="btn primary full" type="submit">가입 완료하고 시작하기</button></form><p style="font-size:13px;margin:15px 0 0">닉네임은 내 정보에서 변경할 수 있습니다.</p></section></main>`;}
function initials(str){const a='ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ';return [...str].map(c=>{const n=c.charCodeAt(0)-44032;return n>=0&&n<=11171?a[Math.floor(n/588)]:c;}).join('');}
function matches(c){const q=searchState.q.trim().toLowerCase(),hay=[c.title,c.genre,c.actors,c.tags].join(' ').toLowerCase();return (searchState.type==='all'||c.type===searchState.type)&&(searchState.genre==='all'||c.genre===searchState.genre)&&(!q||q.split(/\s+/).every(k=>hay.includes(k)||initials(hay).replace(/\s/g,'').includes(k.replace(/\s/g,''))));}
function searchResults(){const list=publics().filter(matches),typo=/항러|항노/.test(searchState.q);return `${typo?`<p style="margin:20px 0;color:var(--accent)">혹시 ‘별의 항로’를 찾으셨나요? ${btn('교정하여 검색','correct','small ghost')}</p>`:''}<div class="rail-head"><h2>검색 결과 <span class="muted">${list.length}개</span></h2></div>${list.length?`<div class="cards">${list.slice(0,catalogLimit).map(c=>card(c)).join('')}</div>${list.length>catalogLimit?`<div class="actions spaced">${btn('더 보기','load-more')}</div>`:''}`:empty('검색 결과가 없습니다','다른 검색어나 필터를 사용해 보세요.')}`;}
function search(){return nav('search')+`<main class="container"><h1 class="section-title">어떤 이야기를 찾고 있나요?</h1><label for="search-q">제목·출연진·장르·태그 검색 · 초성 검색 지원</label><input class="searchbox" id="search-q" placeholder="새로운 이야기를 찾아보세요" value="${esc(searchState.q)}"><div class="filters"><select id="type-filter" aria-label="콘텐츠 유형">${[['all','전체 유형'],['movie','영화'],['series','시리즈']].map(([v,n])=>`<option value="${v}" ${searchState.type===v?'selected':''}>${n}</option>`).join('')}</select><select id="genre-filter" aria-label="장르">${['all',...new Set(publics().map(c=>c.genre))].map(v=>`<option value="${esc(v)}" ${searchState.genre===v?'selected':''}>${v==='all'?'전체 장르':esc(v)}</option>`).join('')}</select>${btn('조건 초기화','clear-search','small ghost')}</div><section id="results" class="spaced">${searchResults()}</section></main>`+footer();}
function detail(id){const c=pick(id);if(!c?.published)return nav()+`<main class="container">${empty('볼 수 없는 콘텐츠입니다','비공개되었거나 삭제된 콘텐츠입니다.','<a class="btn" href="#home">홈으로</a>')}</main>`;const seasons=[...new Set(c.episodes.filter(e=>e.published).map(e=>e.season))],season=Number(new URLSearchParams(location.hash.split('?')[1]).get('season')||seasons[0]||1);return nav()+`<main class="container">${hero(c,true)}<p class="muted spaced">출연 ${esc(c.actors)} · 태그 ${esc(c.tags)}</p>${c.type==='series'?`<div class="rail-head spaced"><h2>에피소드</h2><select id="season-select" data-id="${c.id}" style="width:160px" aria-label="시즌">${seasons.map(n=>`<option ${n===season?'selected':''} value="${n}">시즌 ${n}</option>`).join('')}</select></div><div class="detail-episodes">${c.episodes.filter(e=>e.published&&e.season===season).sort((a,b)=>a.no-b.no).map(e=>`<button class="episode" data-act="play" data-id="${c.id}" data-episode="${e.id}"><img src="${art(c)}" alt="${esc(e.title)}"><h3>${e.no}화 ${esc(e.title)}</h3><p class="meta">42분 · ${esc(c.description)}</p></button>`).join('')}</div>`:''}</main>`+footer();}
const time=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
function savePosition(){if(user()&&player.content){user().history[player.content]=Math.floor(player.position);user().recent=[player.content,...(user().recent||[]).filter(id=>id!==player.content)];persist();}}
function stopPlayer(){clearInterval(playTimer);playTimer=null;if(player.content){savePosition();if(player.playing)event('exit');}player.playing=false;detachMedia();}
// 스트리밍 서버 영상 재생 ---------------------------------------------------------------------
// 스트리밍 서버에서 재생 정보, HLS 재생 목록, 영상 조각을 받는다.
function detachMedia(){if(!media)return;try{media.hls?.destroy();media.video.pause();media.video.removeAttribute('src');media.video.load();}catch{}media=null;}
function mediaError(message){player.status='error';player.message=message;player.playing=false;updatePlayer();toast(message);}
async function attachMedia(id){
 const c=pick(id),video=$('#video');if(!c?.cms||!video)return;
 detachMedia();media={video,hls:null,id};player.status='loading';player.message='';updatePlayer();
 video.volume=player.volume;video.playbackRate=player.speed;
 const mine=()=>media?.video===video;
 video.addEventListener('loadedmetadata',()=>{if(!mine())return;if(Number.isFinite(video.duration))player.duration=video.duration;if(player.position>0&&player.position<player.duration-1)video.currentTime=player.position;else player.position=0;player.status='ready';updatePlayer();});
 video.addEventListener('timeupdate',()=>{if(!mine())return;player.position=video.currentTime;updatePlayer();});
 video.addEventListener('play',()=>{if(!mine())return;player.playing=true;video.style.background='#000';updatePlayer();});
 video.addEventListener('pause',()=>{if(!mine())return;player.playing=false;updatePlayer();});
 video.addEventListener('ended',()=>{if(!mine())return;player.playing=false;savePosition();event('ended');updatePlayer();});
 video.addEventListener('error',()=>{if(mine()&&!media.hls)mediaError('영상을 재생할 수 없습니다.');});
 try{
  const streamingApi=window.STREAMING_API_BASE;
  if(!streamingApi)throw new Error('스트리밍 서버 주소가 설정되지 않았습니다.');
  const res=await fetch(`${streamingApi}/api/v1/contents/${encodeURIComponent(id)}/playback`);
  if(!res.ok)throw new Error(res.status===404?'재생할 수 없는 콘텐츠입니다.':`재생 정보를 받지 못했습니다. (${res.status})`);
  const info=await res.json(),src=streamingApi+info.manifestUrl;
  if(!mine())return;                                   // 응답을 기다리는 사이 다른 화면으로 이동함
  if(window.Hls&&Hls.isSupported()){
   const hls=new Hls();media.hls=hls;
   hls.on(Hls.Events.ERROR,(_,data)=>{if(data.fatal&&mine())mediaError(data.type===Hls.ErrorTypes.NETWORK_ERROR?'스트리밍 서버에서 영상 조각을 받지 못했습니다.':'영상을 재생할 수 없습니다.');});
   hls.loadSource(src);hls.attachMedia(video);
  }else if(video.canPlayType('application/vnd.apple.mpegurl'))video.src=src;   // Safari는 HLS를 직접 재생
  else throw new Error('이 브라우저는 HLS 재생을 지원하지 않습니다.');
 }catch(e){if(mine())mediaError(e.message);}
}
// ----------------------------------------------------------------------------------------------
function startTimer(){clearInterval(playTimer);playTimer=setInterval(()=>{if(!player.playing||!user())return;recordWatch(1);if(media){if(Math.floor(player.position)%15===0){savePosition();event('progress');}return;}player.position=Math.min(2520,player.position+player.speed);updatePlayer();if(Math.floor(player.position)%15===0){savePosition();event('progress');}if(player.position>=2520){player.playing=false;savePosition();event('ended');updatePlayer();}},1000);}
function updatePlayer(){const seek=$('#seek');if(!seek)return;const total=player.duration||2520;if(media)seek.max=total;seek.value=player.position;$('#time-text').textContent=time(player.position)+' / '+time(total);$('#play-toggle').textContent=player.playing?'Ⅱ 일시정지':'▶ 재생';$('#play-center').textContent=player.playing?'Ⅱ':'▶';
 if(!media){$('#play-caption').textContent=player.playing?'시연용 타임라인 재생 중':'시연용 타임라인 · 재생을 눌러 보세요';return;}
 const label=[resLabel(pick(media.id)||{}),'HLS'].filter(Boolean).join(' · ');
 $('#play-caption').textContent=player.status==='error'?player.message+' · 다시 시도하려면 재생을 눌러 주세요':player.status==='loading'?'재생 정보를 불러오는 중…':player.playing?label+' 재생 중':label+' · 재생을 눌러 보세요';
 const center=$('#player-center');if(center)center.style.opacity=player.playing?'0':'1';   // 재생 중에는 가운데 버튼을 숨겨 영상을 가리지 않는다
}
function playerPage(id){if(!user())return loginRequired('재생하려면 로그인해 주세요.');const c=pick(id);if(!c?.published)return detail(id);if(player.content!==id){player={...player,content:id,position:user().history[id]||0,playing:false,duration:c.cms?c.duration||0:2520,status:'',message:''};event('open');}
 const real=!!c.cms;   // CMS 콘텐츠면 실제 영상, 샘플 콘텐츠면 예전의 시연용 타임라인
 return nav()+`<main class="container"><a class="muted" href="#detail/${id}">← ${esc(c.title)} 상세</a><section class="player spaced"><div class="player-stage"${real?' data-act="toggle-play"':''}><img src="${art(c)}" alt="${real?'':'시연용 영상 자리'}">${real?'<video id="video" playsinline preload="metadata" style="position:absolute;inset:0;z-index:1;width:100%;height:100%;object-fit:contain"></video>':''}<div class="player-center" id="player-center"><button id="play-center" class="playbig" data-act="toggle-play" aria-label="재생 또는 일시정지">▶</button><p class="player-caption" id="play-caption">${real?'재생 정보를 불러오는 중…':'시연용 타임라인 · 재생을 눌러 보세요'}</p></div></div><div class="player-controls"><label for="seek" class="sr-label">재생 위치</label><input id="seek" type="range" min="0" max="${real?Math.max(1,player.duration):2520}" step="${real?'0.1':'1'}" value="${player.position}"><div class="play-row">${btn('▶ 재생','toggle-play','small','id="play-toggle"')}${btn('-10초','seek-back','small')}${btn('+10초','seek-forward','small')}<span class="time meta" id="time-text">${time(player.position)} / ${time(player.duration||2520)}</span><label for="volume" style="margin:0;font-size:12px">음량</label><input class="volume" id="volume" type="range" min="0" max="1" step="0.1" value="${player.volume}"><select id="quality" aria-label="화질">${(real?['자동',resLabel(c)].filter(Boolean):['자동','1080p','720p']).map(v=>`<option ${player.quality===v?'selected':''}>${v}</option>`).join('')}</select><select id="subtitle" aria-label="자막">${['한국어','영어','끄기'].map(v=>`<option ${player.subtitle===v?'selected':''}>${v}</option>`).join('')}</select><select id="speed" aria-label="배속">${[.5,1,1.5,2].map(v=>`<option value="${v}" ${player.speed===v?'selected':''}>${v}배</option>`).join('')}</select>${btn('전체 화면','fullscreen','small')}</div><p class="caption">${real?'스트리밍 서버에서 HLS 영상을 재생합니다. 재생 위치·배속·음량은 실제로 동작하며, 화질 전환(ABR)·자막·DRM은 아직 모의 상태입니다.':'실제 영상을 연결하기 전의 시연용 플레이어입니다. 재생 위치·배속·찜·이어보기 흐름은 조작할 수 있습니다. ABR·DRM은 모의 상태입니다.'}</p></div></section></main>`;}
function loginRequired(message){return nav()+`<main class="container">${empty('로그인이 필요합니다',message,'<a href="#login" class="btn primary">소셜로 시작하기</a>')}</main>`;}
function my(){if(!user())return loginRequired('나만의 콘텐츠 목록을 확인해 보세요.');let list=myTab==='watchlist'?user().watchlist.map(pick):Object.keys(user().history).sort((a,b)=>(user().recent?.indexOf(a)??99)-(user().recent?.indexOf(b)??99)).map(pick);list=list.filter(c=>c?.published);return nav('my')+`<main class="container"><h1 class="section-title">내 콘텐츠</h1><section class="panel profile"><div><h2>${esc(user().nickname)}</h2><p class="muted spaced" style="margin-top:8px">나만의 이야기와 감상 기록</p></div><div class="actions">${btn('닉네임 수정','nickname')}${btn('로그아웃','logout')}</div></section><div class="tabs">${[['watchlist','찜한 콘텐츠'],['recent','최근 시청'],['continue','이어보기']].map(([v,l])=>btn(l,'my-tab',myTab===v?'active':'',`data-value="${v}"`)).join('')}</div>${list.length?`<div class="cards">${list.map(c=>card(c,myTab==='continue')).join('')}</div>`:empty('아직 목록이 비어 있습니다','새로운 이야기를 감상하거나 찜해 보세요.','<a href="#search" class="btn">콘텐츠 둘러보기</a>')}</main>`+footer();}
function live(){const list=db.channels.filter(c=>c.published);if(!list.find(c=>c.id===liveChannel))liveChannel=list[0]?.id;const channel=list.find(c=>c.id===liveChannel),programs=db.programs.filter(p=>p.channel===liveChannel).sort((a,b)=>a.start.localeCompare(b.start));return nav('live')+`<main class="container"><h1>지금 라이브</h1><div class="tabs">${list.map(c=>btn('CH · '+esc(c.name),'channel',c.id===liveChannel?'active':'',`data-id="${c.id}"`)).join('')}</div>${channel?`<div class="live-grid"><div><div class="player"><div class="player-stage"><img src="assets/art-3.svg" alt="라이브 샘플 자리"><div class="player-center">${btn(user()?'라이브 시연 시작 ▶':'로그인 후 시청','live-play','primary')}<p class="player-caption">외부 스트림 연결 전 · 편성 시각 예시 14:30</p></div></div></div><h2 class="spaced">${esc(channel.name)}</h2><p class="muted spaced">${esc(channel.description)}</p></div><aside class="panel"><h2>편성표</h2>${programs.length?programs.map((p,i)=>`<div class="schedule-item"><div class="meta">${esc(p.start)} - ${esc(p.end)}</div><h3>${i===0?'지금 · ':i===1?'다음 · ':''}${esc(p.title)}</h3></div>`).join(''):empty('편성된 방송이 없습니다','다른 채널을 선택해 주세요.')}</aside></div>`:empty('공개된 채널이 없습니다','방송을 준비하고 있습니다.')}</main>`+footer();}
function adminShell(section,body){if(!isAdmin())return nav()+`<main class="container">${empty('관리자 권한이 필요합니다','소셜 인증과 관리자 권한은 별도로 확인합니다. 시연 도구에서 관리자 시나리오를 선택할 수 있습니다.',btn('시연 도구','demo'))}</main>`;return `<div class="admin-app"><header class="admin-top"><a class="brand" href="#admin/contents">OTT <span>PROJECT</span></a><span class="page-location">콘텐츠 운영</span><div class="navuser"><span>${esc(user().nickname)}</span><a href="#home" class="btn small">시청자 화면</a>${btn('로그아웃','logout','small ghost')}</div></header><div class="admin-grid"><nav class="sidebar" aria-label="관리자 메뉴">${[['contents','콘텐츠'],['jobs','영상 처리'],['curation','인기 콘텐츠'],['live','라이브 운영'],['recommendations','추천·학습'],['audit','감사 로그']].map(([v,l])=>`<a class="${section===v?'active':''}" href="#admin/${v}">${l}</a>`).join('')}</nav><main class="workspace">${body}</main></div></div>`;}
function heading(title,action=''){return `<div class="page-head"><h1>${title}</h1><div class="actions">${action}</div></div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">조회 결과가 없습니다.</td></tr>`}</tbody></table></div>`;}
function adminContents(){return adminShell('contents',heading('콘텐츠 관리',btn('+ 새 콘텐츠','new-content','primary'))+`<div class="filters"><input id="admin-search" placeholder="작품 제목 검색" style="max-width:440px"><select id="admin-type" aria-label="유형"><option value="all">전체 유형</option><option value="movie">영화</option><option value="series">시리즈</option></select><select id="admin-public" aria-label="공개 상태"><option value="all">전체 공개 상태</option><option value="public">공개</option><option value="private">비공개</option></select></div><div id="content-table">${contentTable()}</div>`);}
function contentTable(){const q=$('#admin-search')?.value||'',type=$('#admin-type')?.value||'all',pub=$('#admin-public')?.value||'all';return table(['작품','유형','영상 상태','공개 상태','관리'],all().filter(c=>c.title.includes(q)&&(type==='all'||c.type===type)&&(pub==='all'||c.published===(pub==='public'))).map(c=>`<tr><td><strong>${esc(c.title)}</strong><small>${c.id}</small></td><td>${c.type==='series'?'시리즈':'영화'}</td><td>${badge(c.type==='series'?c.episodes.filter(e=>e.ready).length+'개 회차 준비':c.ready?'준비 완료':'미준비')}</td><td>${badge(c.published?'공개':'비공개')}</td><td><a class="table-action" href="#admin/edit/${c.id}">편집</a></td></tr>`));}
function editor(id){const c=get(id);if(!c)return adminShell('contents',empty('콘텐츠가 없습니다','목록에서 다시 선택해 주세요.','<a href="#admin/contents" class="btn">목록으로</a>'));let body='';if(editTab==='basic')body=`<form id="content-form" data-id="${id}" novalidate><div class="form-grid">${field('title','제목 *',c.title)}${selectField('type','유형',c.type,[['movie','영화'],['series','시리즈']])}${field('genre','장르 *',c.genre)}${field('year','공개연도 *',c.year)}${field('rating','관람등급 *',c.rating)}${field('actors','출연진',c.actors)}<div class="field span2"><label for="description">소개</label><textarea id="description" name="description">${esc(c.description)}</textarea></div>${field('tags','태그',c.tags)}<div class="error span2" id="content-error" aria-live="polite"></div></div><div class="actions"><button type="submit" class="btn primary">변경사항 저장</button>${btn('목록으로','content-list')}</div></form>`;
 if(editTab==='episodes')body=c.type!=='series'?`<div class="info">시리즈를 선택하면 시즌·에피소드를 관리할 수 있습니다.</div>`:btn('+ 에피소드 추가','new-episode','primary',`data-id="${id}"`)+`<div class="spaced">${table(['시즌·회차','제목','준비·공개','관리'],c.episodes.sort((a,b)=>a.season-b.season||a.no-b.no).map(e=>`<tr><td>시즌 ${e.season} · ${e.no}화</td><td>${esc(e.title)}</td><td>${badge(e.ready?'완료':'미준비')} ${badge(e.published?'공개':'비공개')}</td><td><button class="table-action" data-act="edit-episode" data-id="${id}" data-episode="${e.id}">편집</button> / <button class="table-action" data-act="episode-publish" data-id="${id}" data-episode="${e.id}">${e.published?'비공개':'공개'}</button> / <button class="table-action" data-act="delete-episode" data-id="${id}" data-episode="${e.id}">삭제</button></td></tr>`))}</div>`;
 if(editTab==='media'){const ep=c.type==='series'?(c.episodes.find(e=>e.id===selectedEpisode)||c.episodes[0]):null;selectedEpisode=ep?.id||null;body=`${c.type==='series'?`<div class="field"><label for="episode-media">대상 에피소드</label><select id="episode-media">${c.episodes.map(e=>`<option value="${e.id}" ${e.id===selectedEpisode?'selected':''}>시즌 ${e.season} · ${e.no}화 ${esc(e.title)}</option>`).join('')}</select></div>`:''}<div class="two-columns"><section class="panel"><h2>재생용 원본 영상</h2><p class="muted spaced">현재 연결: ${esc((ep||c).video||'아직 없음')} · ${(ep||c).ready?'준비 완료':'미준비'}</p><div class="upload-zone"><label for="video-upload">새 MP4 파일 선택</label><input id="video-upload" type="file" accept="video/mp4,.mp4" data-id="${id}"></div><p class="caption">파일명·처리 상태만 시연합니다. 실제 업로드·인코딩은 수행하지 않습니다.</p></section><section class="panel"><h2>대표 이미지</h2><img class="spaced" src="assets/art-${c.art}.svg" alt="대표 이미지 예시" style="border-radius:8px"><div class="upload-zone"><label for="image-upload">이미지 교체</label><input id="image-upload" type="file" accept="image/*" data-id="${id}"></div></section></div><div class="info">새 영상이 준비되면 교체하며, 업로드·변환에 실패한 경우 기존 영상을 유지합니다.</div>`;}
 if(editTab==='subtitles')body=`<section class="panel"><h2>다국어 자막</h2>${['한국어','영어'].map(lang=>`<div class="pick-item"><div><strong>${lang}</strong><p class="muted">${c.subtitles.includes(lang)?'자막 등록됨':'등록된 자막 없음'}</p></div>${btn(c.subtitles.includes(lang)?'제거':'샘플 자막 등록','subtitle-toggle','',`data-id="${id}" data-value="${lang}"`)}</div>`).join('')}<p class="caption">샘플 자막 연결 상태를 변경합니다. 실제 자막 파일 검증은 구현 단계에서 진행합니다.</p></section>`;
 return adminShell('contents',heading(esc(c.title),badge(c.published?'공개':'비공개')+btn(c.published?'비공개 전환':'공개 전환','publish','primary',`data-id="${id}"`)+btn('삭제','delete-content','danger',`data-id="${id}"`))+`<div class="tabs">${[['basic','기본 정보'],['episodes','시즌·회차'],['media','영상·이미지'],['subtitles','다국어 자막']].map(([v,l])=>btn(l,'edit-tab',editTab===v?'active':'',`data-value="${v}"`)).join('')}</div>${body}`);}
function field(name,label,value='',extra=''){return `<div class="field"><label for="${name}">${esc(label)}</label><input id="${name}" name="${name}" value="${esc(value)}" ${extra}></div>`;}
function selectField(name,label,value,options){return `<div class="field"><label for="${name}">${esc(label)}</label><select id="${name}" name="${name}">${options.map(([v,n])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`).join('')}</select></div>`;}
function jobs(){return adminShell('jobs',heading('영상 처리 현황')+`<div class="stats">${[['대기·처리 중',db.jobs.filter(j=>['대기','처리 중'].includes(j.status)).length],['완료',db.jobs.filter(j=>j.status==='완료').length],['실패',db.jobs.filter(j=>j.status==='실패').length]].map(([k,v])=>`<div class="stat"><span>${k}</span><strong>${v.toString().padStart(2,'0')}</strong></div>`).join('')}</div>`+table(['대상','원본','출력 화질','상태','관리'],db.jobs.map(j=>`<tr><td>${esc(get(j.content)?.title||'삭제된 콘텐츠')}<small>${j.episode||j.content}</small></td><td>${j.resolution}</td><td>${j.status==='완료'?(j.resolution==='4K'?'4K / 1080p / 720p':'1080p / 720p'):'-'}</td><td>${badge(j.status)}<small>${esc(j.error||'')}</small></td><td>${j.status==='실패'?`<button class="table-action" data-act="retry-job" data-id="${j.id}">재시도</button>`:'<span class="muted">-</span>'}</td></tr>`))+`<div class="info">대기·처리·완료·실패의 모의 상태입니다. 실제 영상 변환은 수행하지 않습니다.</div>`);}
function curation(){
 const rows=popularity();
 return adminShell('curation',heading('인기 콘텐츠 자동 추천',badge('자동 집계'))+`<p class="muted" style="margin-bottom:24px">전체 사용자의 시청 데이터를 바탕으로 홈 인기 목록을 자동으로 구성합니다.</p><div class="stats">${[['집계 기간','최근 7일'],['순위 기준','시청자 수'],['인기 콘텐츠',rows.length+'개']].map(([label,value])=>`<div class="stat"><span>${label}</span><strong style="font-size:26px">${value}</strong></div>`).join('')}</div><section class="panel"><h2>자동 추천 순위</h2><p class="muted spaced">30초 이상 시청한 사용자 수 순 · 동률이면 누적 시청 시간 순</p><p class="caption">화면 조회 시 자동 계산 · ${esc(now())} 기준 · 공개 콘텐츠만 표시</p>${rows.length?table(['순위','콘텐츠','시청자 수','누적 시청 시간','홈 노출'],rows.map((r,i)=>`<tr><td><strong>${i+1}</strong></td><td><strong>${esc(r.content.title)}</strong><small>${r.content.type==='series'?'시리즈':'영화'} · ${esc(r.content.genre)}</small></td><td>${r.viewers}명</td><td>${Math.floor(r.seconds/60)}분 ${Math.floor(r.seconds%60)}초</td><td>${badge(i<5?'노출 중':'후보')}</td></tr>`)):empty('집계할 시청 데이터가 없습니다','시청 데이터가 쌓이면 인기 목록이 자동으로 표시됩니다. 현재 홈은 최신 공개작으로 대체됩니다.')}</section><div class="info">시연 기준: 최근 7일 · 사용자별 작품당 30초 이상 · 같은 사용자의 반복 시청은 1명으로 집계. 실제 서비스의 기간·유효 시청 기준·갱신 주기는 구현범위 선정에서 확정합니다.</div><p class="caption spaced">샘플 전체 사용자 데이터와 이 브라우저의 재생 시연 기록으로 계산합니다. 다른 방문자의 실제 기록을 수집하거나 합산하지 않습니다. 재생 위치 탐색은 시청 시간에 포함하지 않습니다.</p><a href="#home" class="btn spaced">시청자 홈 확인</a>`);
}
function adminLive(){return adminShell('live',heading('라이브 채널·편성 관리',btn('+ 채널 추가','new-channel','primary'))+table(['채널','공개','관리'],db.channels.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.description)}</small></td><td>${badge(c.published?'공개':'비공개')}</td><td><button class="table-action" data-act="edit-channel" data-id="${c.id}">편집</button> / <button class="table-action" data-act="delete-channel" data-id="${c.id}">삭제</button></td></tr>`))+`<div class="page-head spaced"><h2>편성표</h2>${btn('+ 편성 추가','new-program')}</div>`+table(['채널','프로그램','시작','종료','관리'],[...db.programs].sort((a,b)=>a.channel.localeCompare(b.channel)||a.start.localeCompare(b.start)).map(p=>`<tr><td>${esc(db.channels.find(c=>c.id===p.channel)?.name||'-')}</td><td>${esc(p.title)}</td><td>${p.start}</td><td>${p.end}</td><td><button class="table-action" data-act="edit-program" data-id="${p.id}">편집</button> / <button class="table-action" data-act="delete-program" data-id="${p.id}">삭제</button></td></tr>`)));}
function recommendations(){return adminShell('recommendations',heading('추천·학습 데이터')+`<div class="stats">${[['수집 이벤트',12840+db.events.length],['샘플 재시도 대기',18],['사용 중 모델',db.model]].map(([k,v])=>`<div class="stat"><span>${k}</span><strong style="font-size:${typeof v==='string'?'23':'32'}px">${esc(v)}</strong></div>`).join('')}</div><section class="panel"><h2>데이터와 학습</h2><p class="muted spaced">기간별 학습 데이터 · 시연 데이터만 제공</p><div class="form-grid spaced">${field('train-start','시작일','2026-10-01','type="date"')}${field('train-end','종료일','2026-10-31','type="date"')}</div><div class="actions">${btn('데이터 내보내기','export-events')}${btn('학습 실행','train','primary')}${btn('학습 실패 시연','train-fail')}</div></section><div class="spaced">${table(['작업','데이터 버전','모델 버전','상태'],[{id:'TRAIN-014',data:'DATA-010',model:'MODEL-007',status:'완료'},...db.training].reverse().map(t=>`<tr><td>${esc(t.id)}</td><td>${esc(t.data)}</td><td>${esc(t.model||'-')}</td><td>${badge(t.status)}</td></tr>`))}</div><section class="panel spaced"><h2>회원별 추천 예시</h2><p class="spaced">회원 A · 별의 항로 → 푸른 오후 → 깊은 바다</p><p class="spaced">회원 B · 도시의 온도 → 오래된 정원 → 달빛 도서관</p><p class="caption">실제 모델을 학습하지 않습니다. 준비한 추천 순서와 대체 목록으로 동작을 검토합니다.</p></section>`);}
function auditPage(){return adminShell('audit',heading('감사 로그 확인',badge('조회 UI 제안'))+`<div class="info" style="margin:0 0 24px">감사 저장은 FR-30 필수입니다. 이 조회 화면의 실제 구현 여부는 후속 범위 선정에서 결정합니다. 기록은 읽기 전용이며 세션·토큰 등 비밀값을 저장하지 않습니다.</div>`+table(['처리 시각','수행자','작업','대상','결과'],db.logs.map((l,i)=>`<tr><td>${esc(l.time)}</td><td>${esc(l.actor)}</td><td>${esc(l.type)}</td><td>${esc(l.target)}</td><td><button class="table-action" data-act="audit-detail" data-index="${i}">전후 값 보기</button></td></tr>`)));}
function help(){modal('목업 사용 안내',`<p class="muted">입력·검색·찜·이어보기·콘텐츠 편집·공개·편성 검증을 체험할 수 있습니다.</p><div class="spaced"><h3>샘플로 표현하는 기능</h3><p class="muted spaced">소셜 인증·서버 세션·재생 타임라인·DRM/ABR·업로드/인코딩·AI 추천/학습은 모의 동작입니다. 실제 외부 서비스에 연결하지 않습니다.</p><h3 class="spaced">반복 시연</h3><p class="muted spaced">오른쪽 아래 ‘시연 도구’에서 회원·관리자 시나리오와 오류 상태를 선택할 수 있습니다. 입력 데이터는 이 브라우저에만 저장됩니다.</p></div><div class="actions">${btn('확인','close','primary')}</div>`);}
function demo(){modal('시연 도구 · 제품 메뉴와 별도',`<p class="muted">샘플 계정과 오류 상태를 선택합니다. 실제 서비스에서 회원이 역할을 바꾸는 기능은 아닙니다.</p><div class="demo-options">${[['new','신규 회원','소셜 인증 → 닉네임 → 첫 홈'],['a','기존 회원 A','추천·찜·이어보기 샘플'],['b','기존 회원 B','다른 시청 이력·추천 순서'],['admin','관리자','콘텐츠 등록·공개·운영']].map(([v,l,d])=>`<button class="demo-option" data-act="scenario" data-value="${v}"><strong>${l}</strong><small>${d}</small></button>`).join('')}</div><div class="demo-shortcuts">${btn('세션 만료','expire','small')}${btn(db.recommendationFailure?'추천 정상 복구':'추천 장애','rec-failure','small')}${btn('DRM 오류','drm-error','small')}${btn('초기 데이터로 복원','reset','small danger')}</div><p class="caption">세션 ID·소셜 토큰을 생성하지 않으며 샘플 회원 ID로 화면 데이터만 분리합니다.</p>`);}
function openEpisode(content,id){const c=get(content),e=c.episodes.find(e=>e.id===id);modal(e?'에피소드 편집':'에피소드 추가',`<form id="episode-form" data-content="${content}" data-id="${id||''}" novalidate><div class="form-grid">${field('season','시즌 *',e?.season||1,'type="number" min="1"')}${field('no','회차 *',e?.no||c.episodes.filter(e=>e.season===1).length+1,'type="number" min="1"')}${field('episode-title','제목 *',e?.title||'')}</div><div class="error" id="episode-error"></div><div class="actions"><button class="btn primary" type="submit">저장</button>${btn('취소','close')}</div></form>`);}
function channelForm(id){const c=db.channels.find(c=>c.id===id);modal(c?'채널 편집':'채널 추가',`<form id="channel-form" data-id="${id||''}" novalidate>${field('channel-name','채널명 *',c?.name||'')}${field('channel-description','설명',c?.description||'')}${field('channel-url','외부 HLS 주소 *',c?.url||'https://stream.example/live/new.m3u8')}${selectField('channel-public','공개 여부',c?.published?'yes':'no',[['yes','공개'],['no','비공개']])}<div class="error" id="channel-error"></div><div class="actions"><button class="btn primary">저장</button>${btn('취소','close')}</div></form>`);}
function programForm(id){const p=db.programs.find(p=>p.id===id);if(!db.channels.length)return toast('채널을 먼저 추가해 주세요.');modal(p?'편성 수정':'편성 추가',`<form id="program-form" data-id="${id||''}" novalidate>${selectField('program-channel','채널',p?.channel||db.channels[0].id,db.channels.map(c=>[c.id,c.name]))}${field('program-title','프로그램 제목 *',p?.title||'')}<div class="form-grid">${field('program-start','시작 시각 *',p?.start||'17:00','type="time"')}${field('program-end','종료 시각 *',p?.end||'18:00','type="time"')}</div><div class="error" id="program-error" aria-live="polite"></div><div class="actions"><button class="btn primary">저장</button>${btn('취소','close')}</div></form>`);}
function publish(id){const c=get(id);if(!c)return;if(!c.published){const ready=c.type==='movie'?c.ready:c.episodes.some(e=>e.ready&&e.published);if(!ready)return toast('재생 가능한 영상 또는 공개 가능한 에피소드가 필요합니다.');if(!c.title.trim()||!c.genre.trim()||!c.year||!c.rating)return toast('필수 콘텐츠 정보를 먼저 입력해 주세요.');}const before={published:c.published};c.published=!c.published;if(c.published)c.created=Date.now();audit(c.published?'공개 전환':'비공개 전환',id,before,{published:c.published});toast(c.published?'콘텐츠를 공개했습니다.':'비공개로 전환했습니다.');render();}
function runJob(j){if(j.status==='처리 중')return;j.status='처리 중';j.error='';persist();render();setTimeout(()=>{j.status='완료';const c=get(j.content);if(c){const target=j.episode?c.episodes.find(e=>e.id===j.episode):c;if(target){target.ready=true;target.video=j.filename||target.video||'sample.mp4';}audit('영상 처리 완료',c.id,{ready:false},{ready:true});}persist();if(location.hash.startsWith('#admin'))render();toast('모의 영상 처리가 완료되었습니다.');},1800);}
function training(fail=false){const start=$('#train-start')?.value,end=$('#train-end')?.value;if(!start||!end||start>end)return toast('올바른 데이터 기간을 선택해 주세요.');if(db.training.some(t=>t.status==='진행 중'))return toast('학습 작업이 이미 진행 중입니다.');const t={id:'TRAIN-'+(15+db.training.length),data:'DATA-'+(++db.dataVersion),model:null,status:'진행 중'};db.training.push(t);persist();render();setTimeout(()=>{t.status=fail?'실패':'완료';if(!fail){t.model='MODEL-'+(8+db.training.filter(x=>x.status==='완료').length).toString().padStart(3,'0');db.model=t.model;}audit('추천 학습 '+t.status,t.id,null,{model:db.model,status:t.status});if(location.hash==='#admin/recommendations')render();toast(fail?'학습 실패 · 기존 정상 모델을 유지합니다.':'모의 학습 완료 · 모델 버전을 갱신했습니다.');},1800);}
function render(){const path=location.hash.slice(1)||'home',parts=path.split('?')[0].split('/');if(parts[0]!=='player'&&player.content){stopPlayer();player.content=null;}closeModal();let html;if(parts[0]==='home')html=home();else if(parts[0]==='login')html=login();else if(parts[0]==='signup')html=signup();else if(parts[0]==='search')html=search();else if(parts[0]==='detail')html=detail(parts[1]);else if(parts[0]==='player')html=playerPage(parts[1]);else if(parts[0]==='my')html=my();else if(parts[0]==='live')html=live();else if(parts[0]==='admin'){html=!isAdmin()?adminShell('contents',''):parts[1]==='edit'?editor(parts[2]):({contents:adminContents,jobs,curation,live:adminLive,recommendations,audit:auditPage}[parts[1]]||adminContents)();}else html=home();$('#app').innerHTML=html+demoBar();document.title=`OTT PROJECT · ${parts[0]==='admin'?'관리자 목업':'클릭형 목업'}`;if(parts[0]==='player'&&user()){updatePlayer();startTimer();attachMedia(parts[1]);}window.scrollTo(0,0);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;const a=el.dataset.act,id=el.dataset.id,v=el.dataset.value;const adminActions=['new-content','publish','delete-content','edit-tab','new-episode','edit-episode','episode-publish','delete-episode','retry-job','new-channel','edit-channel','delete-channel','new-program','edit-program','delete-program','train','train-fail','export-events','audit-detail','subtitle-toggle'];if(adminActions.includes(a)&&!isAdmin())return toast('관리자 권한이 필요합니다.');
 if(a==='close')closeModal();else if(a==='help')help();else if(a==='demo')demo();else if(a==='detail')go('detail/'+id);else if(a==='content-list')go('admin/contents');
 else if(a==='social')modal('소셜 인증 · 모의 화면',`<span class="mock-label">외부 서비스 연결 없음</span><p class="muted spaced">인증 완료 후 ${demoActor==='new'?'닉네임 설정 화면':'기존 회원 홈'}으로 이동합니다. 실제 계정 정보를 입력하지 마세요.</p><div class="actions">${btn('인증 완료','social-success','primary')}${btn('인증 취소','social-cancel')}${btn('실패 시연','social-fail')}</div>`);
 else if(a==='social-success'){closeModal();if(demoActor==='new')go('signup');else{db.current=demoActor;persist();go('home');toast('로그인되었습니다.');}}
 else if(a==='social-cancel'){closeModal();toast('로그인이 취소되었습니다. 계정을 생성하지 않았습니다.');}
 else if(a==='social-fail'){closeModal();toast('로그인을 완료하지 못했습니다. 다시 시도해 주세요.');}
 else if(a==='scenario'){stopPlayer();demoActor=v;db.current=v==='new'?null:v;persist();closeModal();go(v==='new'?'login':v==='admin'?'admin/contents':'home');toast(v==='new'?'신규 회원 시나리오입니다.':'샘플 계정으로 시연을 시작합니다.');}
 else if(a==='logout'||a==='expire'){stopPlayer();db.current=null;demoActor='a';persist();go('login');toast(a==='expire'?'로그인이 만료되었습니다. 다시 로그인해 주세요.':'로그아웃했습니다.');}
 else if(a==='watchlist'){if(!user()){toast('찜하려면 로그인해 주세요.');return go('login');}const list=user().watchlist,idx=list.indexOf(id);idx<0?list.push(id):list.splice(idx,1);persist();render();toast(idx<0?'찜 목록에 추가했습니다.':'찜 목록에서 제거했습니다.');}
 else if(a==='play'){if(!user()){toast('재생하려면 로그인해 주세요.');return go('login');}selectedEpisode=el.dataset.episode||null;go('player/'+id);}
 else if(a==='toggle-play'){if(media){if(player.status==='error')return attachMedia(media.id);if(player.status!=='ready')return;const willPlay=media.video.paused;if(willPlay)media.video.play().catch(()=>mediaError('영상을 재생할 수 없습니다.'));else media.video.pause();savePosition();event(willPlay?'play':'pause');}else{player.playing=!player.playing;savePosition();event(player.playing?'play':'pause');updatePlayer();}}
 else if(a==='seek-back'||a==='seek-forward'){player.position=Math.max(0,Math.min(player.duration||2520,player.position+(a==='seek-back'?-10:10)));if(media&&player.status==='ready')media.video.currentTime=player.position;savePosition();event('seek');updatePlayer();}
 else if(a==='fullscreen'){const p=$('.player');if(document.fullscreenElement)document.exitFullscreen?.();else p?.requestFullscreen?.().catch(()=>toast('이 브라우저에서 전체 화면을 사용할 수 없습니다.'));}
 else if(a==='my-tab'){myTab=v;render();}else if(a==='nickname')modal('닉네임 수정',`<form id="nickname-form" novalidate>${field('new-nickname','닉네임 *',user().nickname)}<div class="error" id="nickname-error"></div><div class="actions"><button class="btn primary">저장</button></div></form>`);
 else if(a==='clear-search'){searchState={q:'',type:'all',genre:'all'};render();}else if(a==='correct'){searchState.q='별의 항로';render();}else if(a==='load-more'){catalogLimit+=10;$('#results').innerHTML=searchResults();}
 else if(a==='channel'){liveChannel=id;render();}else if(a==='live-play'){if(!user())return go('login');modal('라이브 시연',`<p class="muted">외부 HLS 연결 전의 시연입니다. 채널과 편성표 이동을 검토할 수 있습니다.</p><div class="actions">${btn('스트림 오류 시연','live-error')}${btn('확인','close','primary')}</div>`);}else if(a==='live-error')modal('라이브 영상을 재생할 수 없습니다',`<p class="muted">연결 상태를 확인하거나 다른 채널을 선택해 주세요.</p><div class="actions">${btn('다시 시도','live-play','primary')}${btn('닫기','close')}</div>`);
 else if(a==='new-content')modal('새 콘텐츠',`<form id="new-content-form" novalidate>${field('new-title','제목 *','')}${selectField('new-type','유형','movie',[['movie','영화'],['series','시리즈']])}<div class="error" id="new-content-error"></div><div class="actions"><button class="btn primary">비공개로 만들기</button></div></form>`);
 else if(a==='edit-tab'){editTab=v;render();}else if(a==='publish')publish(id);
 else if(a==='delete-content')modal('콘텐츠를 삭제할까요?',`<p class="muted">${esc(get(id)?.title)}는 사용자 목록·검색·추천에서 제외되고 새 재생도 차단됩니다.</p><div class="actions">${btn('삭제하기','confirm-delete-content','danger',`data-id="${id}"`)}${btn('취소','close')}</div>`);
 else if(a==='confirm-delete-content'&&isAdmin()){const c=get(id);audit('삭제',id,{title:c.title,published:c.published},null);c.deleted=true;persist();go('admin/contents');toast('콘텐츠를 삭제했습니다.');}
 else if(a==='new-episode'||a==='edit-episode')openEpisode(id,el.dataset.episode);
 else if(a==='delete-episode'){const c=get(id),ep=c.episodes.find(x=>x.id===el.dataset.episode);if(!confirm(`${ep.title} 에피소드를 삭제할까요?`))return;const before={...ep};c.episodes=c.episodes.filter(x=>x.id!==ep.id);audit('에피소드 삭제',ep.id,before,null);render();}
 else if(a==='episode-publish'){const c=get(id),ep=c.episodes.find(x=>x.id===el.dataset.episode);if(!ep.published&&!ep.ready)return toast('에피소드 영상 준비가 필요합니다.');ep.published=!ep.published;audit('에피소드 공개 변경',ep.id,null,{published:ep.published});render();}
 else if(a==='retry-job')runJob(db.jobs.find(j=>j.id===id));
 else if(a==='new-channel'||a==='edit-channel')channelForm(id);
 else if(a==='delete-channel'){if(!confirm('채널과 연결된 편성을 삭제할까요?'))return;const c=db.channels.find(c=>c.id===id);db.channels=db.channels.filter(c=>c.id!==id);db.programs=db.programs.filter(p=>p.channel!==id);audit('채널 삭제',id,c,null);render();}
 else if(a==='new-program'||a==='edit-program')programForm(id);
 else if(a==='delete-program'){const p=db.programs.find(p=>p.id===id);db.programs=db.programs.filter(p=>p.id!==id);audit('편성 삭제',id,p,null);render();}
 else if(a==='train'||a==='train-fail')training(a==='train-fail');
 else if(a==='export-events'){const data=db.events.map(({id,member,content,type,time,position})=>({id,member,content,type,time,position}));const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='ott-sample-events.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('샘플 이벤트만 내려받았습니다.');}
 else if(a==='audit-detail'){const l=db.logs[Number(el.dataset.index)];modal('감사 기록 · 읽기 전용',`<p class="muted">${esc(l.type)} / ${esc(l.target)} / ${esc(l.actor)}</p><h3 class="spaced">변경 전</h3><pre class="mono">${esc(JSON.stringify(l.before,null,2))}</pre><h3 class="spaced">변경 후</h3><pre class="mono">${esc(JSON.stringify(l.after,null,2))}</pre>`);}
 else if(a==='subtitle-toggle'){const c=get(id),before=[...c.subtitles];c.subtitles=c.subtitles.includes(v)?c.subtitles.filter(x=>x!==v):[...c.subtitles,v];audit('자막 변경',id,{languages:before},{languages:c.subtitles});render();}
 else if(a==='rec-failure'){db.recommendationFailure=!db.recommendationFailure;persist();go('home');toast(db.recommendationFailure?'추천 장애 · 인기 콘텐츠 또는 최신작으로 대체합니다.':'추천이 정상 복구되었습니다.');}
 else if(a==='drm-error')modal('보호된 영상을 재생할 수 없습니다',`<p class="muted">DRM 재생 권한이 유효하지 않은 모의 상태입니다. 로그인 세션과 별도 권한으로 검증됩니다.</p><div class="actions">${btn('다시 확인','close','primary')}</div>`);
 else if(a==='reset')modal('초기 데이터로 복원할까요?',`<p class="muted">이 브라우저에서 바꾼 샘플 계정·콘텐츠·시청 기록·편성이 초기화됩니다.</p><div class="actions">${btn('초기화','confirm-reset','danger')}${btn('취소','close')}</div>`);
 else if(a==='confirm-reset'){stopPlayer();db=seed();demoActor='new';persist();go('home');toast('초기 데이터로 복원했습니다.');}
});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form),val=k=>String(fd.get(k)||'').trim();
 if(form.id==='signup-form'){const name=val('nickname');if(!name)return $('#signup-error').textContent='닉네임을 입력해 주세요.';const id=uid('member');db.users[id]={id,nickname:name,role:'member',watchlist:[],history:{}};db.current=id;demoActor=id;persist();go('home');toast('가입이 완료되었습니다.');}
 else if(form.id==='nickname-form'){const name=val('new-nickname');if(!name)return $('#nickname-error').textContent='닉네임을 입력해 주세요.';user().nickname=name;persist();render();toast('닉네임을 저장했습니다.');}
 else if(!isAdmin())return toast('관리자 권한이 필요합니다.');
 else if(form.id==='new-content-form'){if(!val('new-title'))return $('#new-content-error').textContent='제목을 입력해 주세요.';const c={id:uid('c'),title:val('new-title'),type:val('new-type'),genre:'',year:'2026',rating:'12+',actors:'',tags:'',description:'',art:Math.floor(Math.random()*6),published:false,ready:false,video:'',image:'',episodes:[],subtitles:[],deleted:false,created:Date.now()};db.contents.push(c);audit('콘텐츠 등록',c.id,null,{title:c.title,published:false});editTab='basic';go('admin/edit/'+c.id);}
 else if(form.id==='content-form'){const c=get(form.dataset.id);if(!val('title')||!val('genre')||!/^\d{4}$/.test(val('year'))||!val('rating'))return $('#content-error').textContent='제목·장르·4자리 공개연도·관람등급을 입력해 주세요.';const before={...c};for(const k of ['title','type','genre','year','rating','actors','tags','description'])c[k]=val(k);audit('콘텐츠 수정',c.id,before,{...c});toast('변경사항을 저장했습니다.');render();}
 else if(form.id==='episode-form'){const c=get(form.dataset.content),season=Number(val('season')),no=Number(val('no'));if(!val('episode-title')||!Number.isInteger(season)||season<1||!Number.isInteger(no)||no<1)return $('#episode-error').textContent='시즌·회차·제목을 올바르게 입력해 주세요.';if(c.episodes.some(x=>x.season===season&&x.no===no&&x.id!==form.dataset.id))return $('#episode-error').textContent='같은 시즌에 동일한 회차가 이미 있습니다.';const old=c.episodes.find(x=>x.id===form.dataset.id),ep=old||{id:uid('ep'),ready:false,published:false,video:''},before=old?{...old}:null;Object.assign(ep,{season,no,title:val('episode-title')});if(!old)c.episodes.push(ep);audit('에피소드 '+(old?'수정':'등록'),ep.id,before,{...ep});render();toast('에피소드를 저장했습니다.');}
 else if(form.id==='channel-form'){if(!val('channel-name')||!/^https?:\/\//.test(val('channel-url')))return $('#channel-error').textContent='채널명과 http(s) 재생 주소를 입력해 주세요.';const old=db.channels.find(c=>c.id===form.dataset.id),c=old||{id:uid('ch')},before=old?{...old}:null;Object.assign(c,{name:val('channel-name'),description:val('channel-description'),url:val('channel-url'),published:val('channel-public')==='yes'});if(!old)db.channels.push(c);audit('채널 '+(old?'수정':'등록'),c.id,before,{...c});render();toast('채널을 저장했습니다.');}
 else if(form.id==='program-form'){const channel=val('program-channel'),start=val('program-start'),end=val('program-end'),title=val('program-title');if(!title||!start||!end||end<=start)return $('#program-error').textContent='제목과 올바른 시작·종료 시각이 필요합니다. 종료는 시작보다 늦어야 합니다.';if(db.programs.some(p=>p.channel===channel&&p.id!==form.dataset.id&&start<p.end&&end>p.start))return $('#program-error').textContent='같은 채널의 방송 시간이 겹칩니다. 인접 편성은 허용합니다.';const old=db.programs.find(p=>p.id===form.dataset.id),p=old||{id:uid('p')},before=old?{...old}:null;Object.assign(p,{channel,start,end,title});if(!old)db.programs.push(p);audit('편성 '+(old?'수정':'등록'),p.id,before,{...p});render();toast('편성을 저장했습니다.');}
});
document.addEventListener('input',e=>{if(e.target.id==='search-q'){searchState.q=e.target.value;catalogLimit=10;$('#results').innerHTML=searchResults();}else if(e.target.id==='admin-search')$('#content-table').innerHTML=contentTable();else if(e.target.id==='seek'){player.position=Number(e.target.value);if(media&&player.status==='ready')media.video.currentTime=player.position;savePosition();updatePlayer();}else if(e.target.id==='volume'){player.volume=Number(e.target.value);if(media)media.video.volume=player.volume;}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='type-filter'||el.id==='genre-filter'){searchState[el.id==='type-filter'?'type':'genre']=el.value;$('#results').innerHTML=searchResults();}else if(['admin-type','admin-public'].includes(el.id))$('#content-table').innerHTML=contentTable();else if(el.id==='season-select')go('detail/'+el.dataset.id+'?season='+el.value);else if(el.id==='episode-media'){selectedEpisode=el.value;render();}else if(el.id==='speed'){player.speed=Number(el.value);if(media)media.video.playbackRate=player.speed;toast(media?'재생 속도를 변경했습니다.':'시연 타임라인 배속을 변경했습니다.');}else if(el.id==='quality'||el.id==='subtitle'){player[el.id]=el.value;toast(el.id==='quality'?'화질 선택 상태를 변경했습니다. 실제 ABR은 모의 처리입니다.':'자막 선택 상태를 변경했습니다.');}else if(el.id==='volume'){player.volume=Number(el.value);if(media)media.video.volume=player.volume;}else if(['video-upload','image-upload'].includes(el.id)){if(!isAdmin())return;const file=el.files[0],c=get(el.dataset.id);if(!file||!c)return;if(el.id==='video-upload'){if(!/\.mp4$/i.test(file.name))return toast('MP4 형식만 등록할 수 있습니다.');const job={id:uid('job'),content:c.id,episode:c.type==='series'?selectedEpisode:null,status:'대기',resolution:'1080p',error:'',filename:file.name};if(c.type==='series'&&!selectedEpisode)return toast('에피소드를 먼저 추가해 주세요.');db.jobs.unshift(job);audit('원본 등록',c.id,null,{filename:file.name});toast('원본을 등록했습니다. 모의 영상 처리를 시작합니다.');runJob(job);}else{if(!file.type.startsWith('image/'))return toast('이미지 파일을 선택해 주세요.');audit('대표 이미지 교체',c.id,{filename:c.image},{filename:file.name});c.image=file.name;c.art=(c.art+1)%6;persist();render();toast('샘플 대표 이미지로 교체했습니다.');}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const list=$$('button,a,input,select,textarea',$('.modal')).filter(n=>!n.disabled&&n.getClientRects().length);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',render);window.addEventListener('beforeunload',savePosition);
persist();render();loadCms();
